draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  // burden
  ctx.beginPath();
  ctx.rect(W/2 - 20, H/2 + 50, 40, 20);
  ctx.stroke();

  // forgiveness
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 80, 10 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // releasing burden
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 50 + 20*Math.sin(t));
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  ctx.restore();
}
